secureScript.script:
import jenkins.model.Jenkins

// 1. Initialize the list with your default option ONLY
def finalOptions = ["--- TRIGGER NEW BUILD ---"] 
def folderList = []

try {
    def jenkinsHome = Jenkins.get().getRootDir().getAbsolutePath()
    def buildFolder = new File(jenkinsHome, "../builds/FILE_NEI_PACKAGE")

    if (buildFolder.exists() && buildFolder.isDirectory()) {
        buildFolder.eachDir { dir ->
            folderList.add(dir.name)
        }

        // 2. Sort the folders descending (newest timestamps first)
        folderList.sort().reverse()

        // 3. Add the sorted folders AFTER the default option
        finalOptions.addAll(folderList)
    }
} catch (Exception e) {
    return ["--- TRIGGER NEW BUILD ---", "Error: " + e.message]
}

// 4. Return the combined list where index 0 is always your TRIGGER option
return finalOptions
